      const buildings=await rows('buildings',`&owner_id=eq.${encodeURIComponent(id)}`),bids=(buildings||[]).map(x=>String(x.id));
      const units=bids.length?await rows('units',`&building_id=in.(${bids.map(encodeURIComponent).join(',')})`):[];const uids=(units||[]).map(x=>String(x.id));
      const links=uids.length?await rows('tenant_units',`&unit_id=in.(${uids.map(encodeURIComponent).join(',')})`):[];const tids=[...new Set((links||[]).map(x=>String(x.tenant_id)))];
      const tenants=tids.length?await rows('tenants',`&id=in.(${tids.map(encodeURIComponent).join(',')})`):[];const payments=tids.length?await rows('payments',`&tenant_id=in.(${tids.map(encodeURIComponent).join(',')})`):[];
      const ibans=await rows('owner_bank_accounts',`&owner_id=eq.${encodeURIComponent(id)}`);
