      const units=await rows('units',`&building_id=eq.${encodeURIComponent(id)}`),uids=(units||[]).map(x=>String(x.id));const links=uids.length?await rows('tenant_units',`&unit_id=in.(${uids.map(encodeURIComponent).join(',')})`):[];const tids=[...new Set((links||[]).map(x=>String(x.tenant_id)))];const tenants=tids.length?await rows('tenants',`&id=in.(${tids.map(encodeURIComponent).join(',')})`):[];const utils=await rows('utility_ean_codes',`&building_id=eq.${encodeURIComponent(id)}`);summary=[{label:'Units',value:(units||[]).length},{label:'Tenants',value:(tenants||[]).length},{label:'Utilities',value:(utils||[]).length},{label:'Address',value:b.address||'—'}];sections.push({key:'overview',title:'Building details',items:[pick(b,['name','address','city','postal_code','country','notes'])]},{key:'units',title:'Units',items:(units||[]).map(x=>pick(x,['name','unit_number','floor','type','bedrooms','surface']))},{key:'tenants',title:'Tenants',items:(tenants||[]).map(x=>pick(x,['name','email','phone','tenancy_type','monthly_rent','active']))},{key:'utilities',title:'Utilities',items:(utils||[]).map(x=>pick(x,['utility_type','ean','meter_number','scope']))});
